import java.util.*;public class Knn{public record Point(double x,double y,String label){}public static String classify(List<Point> p,double tx,double ty,int k){p.sort(Comparator.comparingDouble(x->Math.hypot(x.x()-tx,x.y()-ty)));Map<String,Integer>v=new HashMap<>();for(int i=0;i<Math.min(k,p.size());i++)v.merge(p.get(i).label(),1,Integer::sum);return v.entrySet().stream().max(Map.Entry.comparingByValue()).get().getKey();}}